    /** Flag controlling whether the parser should autodetect the charset of the input stream. */
    private boolean autodetectCharset;

    static {
        // Configure the parser once with secure options.
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(true); // Default; can be overridden per request.
