import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    static public File allocateFile(File dir, String name) {
        // Remove query parameters if present
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve the target file path relative to the intended directory
        Path dirPath = dir.toPath().toAbsolutePath().normalize();
        Path targetPath = dirPath.resolve(name).normalize();

        // Ensure the resolved path stays within the intended directory
        if (!targetPath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                "Attempted to create a file outside the intended directory: " + name);
        }

        // Construct the File object from the validated path
        File file = targetPath.toFile();

        // Determine prefix and suffix for duplicate handling
        int dot = name.lastIndexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);

        // Append numeric suffixes until a unique filename is found
        int index = 2;
        while (file.exists()) {
            String newName = prefix + "-" + index++ + suffix;
            targetPath = dirPath.resolve(newName).normalize();
            if (!targetPath.startsWith(dirPath)) {
                throw new IllegalArgumentException(
                    "Duplicate filename resolution attempted to escape directory: " + newName);
            }
            file = targetPath.toFile();
        }

        // Ensure parent directories exist
        File parentDir = file.getParentFile();
        if (parentDir != null && !parentDir.exists()) {
            boolean dirsCreated = parentDir.mkdirs();
            if (!dirsCreated && !parentDir.isDirectory()) {
                throw new RuntimeException("Failed to create directories for: " + parentDir);
            }
        }

        return file;
    }

    // other methods

}
