import javax.ws.rs.ext.RuntimeDelegate;

public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate
{
   // other methods

   /**
    * Validates a media type component (major or subtype) according to RFC 7231.
    *
    * <p>The RFC specifies that a media type component must consist of one or more
    * token characters. A token is defined as any CHAR except CTLs or separators.
    * Separators are: {@code ()<>@,;:\\\"/[]?=}. CTLs are control characters
    * (values <= 31 or 127). Therefore, we accept only printable ASCII characters
    * that are not separators.</p>
    *
    * @param str the component string to validate
    * @return {@code true} if the string is a valid token, {@code false} otherwise
    */
   protected static boolean isValid(String str) {
      if (str == null || str.isEmpty()) {
         return false;
      }
      for (int i = 0; i < str.length(); i++) {
         char ch = str.charAt(i);
         // Reject control characters (<= 31 or 127)
         if (ch <= 31 || ch == 127) {
            return false;
         }
         // Reject separator characters
         switch (ch) {
            case '(':
            case ')':
            case '<':
            case '>':
            case '@':
            case ',':
            case ';':
            case ':':
            case '\\':
            case '"':
            case '/':
            case '[':
            case ']':
            case '?':
            case '=':
               return false;
            default:
               break;
         }
      }
      return true;
   }

   // other methods

}
