     * Decompresses data from the given {@link InputStream} into the provided output buffer.
     *
     * <p>This method has been patched to guard against malformed input that could cause an
     * infinite loop or excessive memory consumption. The key changes are:</p>
     *
     * <ul>
     *   <li>All calls to {@code in.read()} now check for {@code -1} (end-of-stream). If the
     *       stream ends prematurely, an {@link IOException} is thrown.</li>
     *   <li>The loop condition has been tightened to ensure that {@code position} never
     *       exceeds {@code total}. The inner loops now use a local counter that is bounded
     *       by the remaining space in the output buffer.</li>
     *   <li>A sanity check ensures that the run-length value {@code n} is within the valid
     *       range (0–255). Values outside this range trigger an exception.</li>
     * </ul>
     *
     * @param in  the input stream containing compressed data
     * @param out the output buffer to receive decompressed data
     * @throws IOException if the input stream ends unexpectedly or contains invalid data
     */
    private static void decompress(final InputStream in, final byte[] out) throws IOException {
        int position = 0;
        final int total = out.length;

        while (position < total) {
            final int n = in.read();
            if (n == -1) {
                throw new IOException("Unexpected end of stream while reading run length");
            }

            if (n < 0 || n > 255) {
                throw new IOException("Invalid run length value: " + n);
            }

            if (n > 128) {
                final int value = in.read();
                if (value == -1) {
                    throw new IOException("Unexpected end of stream while reading repeated value");
                }

                final int repeatCount = n & 0x7F;
                if (repeatCount == 0) {
                    throw new IOException("Run length of zero encountered in repeat mode");
                }

                if (position + repeatCount > total) {
                    throw new IOException("Decompressed data would exceed output buffer size");
                }

                final byte b = (byte) value;
                for (int i = 0; i < repeatCount; i++) {
                    out[position++] = b;
                }
            } else {
                if (n == 0) {
                    throw new IOException("Run length of zero encountered in literal mode");
                }

                if (position + n > total) {
                    throw new IOException("Decompressed data would exceed output buffer size");
                }

                for (int i = 0; i < n; i++) {
                    final int literal = in.read();
                    if (literal == -1) {
                        throw new IOException("Unexpected end of stream while reading literal value");
                    }
                    out[position++] = (byte) literal;
                }
            }
        }
