        String[] rawUrls = StringUtils.tokenizeToStringArray(resourceUrl, RESOURCE_URL_DELIMITERS);
        List<String> sanitizedUrls = new ArrayList<>();

        for (String rawUrl : rawUrls) {
            // Trim whitespace and normalize path separators
            String trimmedUrl = rawUrl.trim();

            // Reject empty URLs
            if (trimmedUrl.isEmpty()) {
                continue;
