    private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
        // Resolve the canonical path of the target directory once
        Path canonicalTargetDir = targetDirectory.getCanonicalFile().toPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            // Sanitize the entry name by removing leading slashes and normalizing path separators
            String sanitizedEntryName = sanitizeEntryName(nextEntry.getName());

            // Construct the destination file using the sanitized entry name
            File destFile = new File(targetDirectory, sanitizedEntryName);

            // Resolve the canonical path of the destination file
            Path canonicalDestPath = destFile.getCanonicalFile().toPath();

            // Ensure the destination file resides within the target directory
            if (!canonicalDestPath.startsWith(canonicalTargetDir)) {
                throw new IOException("expanding " + nextEntry.getName()
                        + " would create file outside of " + targetDirectory);
            }

            if (nextEntry.isDirectory()) {
                // Create the directory if it does not exist
                if (!destFile.isDirectory() && !destFile.mkdirs()) {
                    throw new IOException("failed to create directory " + destFile);
                }
            } else {
                // Ensure parent directories exist
                File parent = destFile.getParentFile();
                if (!parent.isDirectory() && !parent.mkdirs()) {
                    throw new IOException("failed to create directory " + parent);
                }

                // Write the entry data to the destination file
                try (OutputStream out = Files.newOutputStream(destFile.toPath())) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    /**
     * Sanitizes an archive entry name by removing leading slashes and normalizing path separators.
     *
     * @param entryName the raw entry name from the archive
     * @return a sanitized entry name safe for file extraction
     */
    private String sanitizeEntryName(String entryName) {
        // Remove leading slashes to prevent absolute path extraction
        while (entryName.startsWith("/") || entryName.startsWith("\\")) {
            entryName = entryName.substring(1);
        }

        // Replace backslashes with forward slashes for consistency
        entryName = entryName.replace("\\", "/");

        // Collapse any redundant separators
        entryName = entryName.replaceAll("/{2,}", "/");

        // Prevent entries that resolve to the root directory
        if (entryName.isEmpty() || entryName.equals(".")) {
            return "";
        }

        return entryName;
    }

